# Label utility

trimLabel removes leading and trailing whitespace and returns a string, including for empty or whitespace-only input.

Supported environments: Linux and Windows, Node.js 24.

The files under ci/ are synthetic CI logs supplied for this exercise, not real production runs. Both describe the same candidate version.
{
  "name": "label-fixture",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --test"
  }
}
export function trimLabel(value) {
  return value.trim();
}
import assert from "node:assert/strict";
import test from "node:test";
import { trimLabel } from "../src/trim-label.js";

test("empty input remains an empty string", () => {
  assert.equal(trimLabel(""), "");
});

test("whitespace-only input becomes an empty string", () => {
  assert.equal(trimLabel("  \t "), "");
});

test("surrounding whitespace is trimmed", () => {
  assert.equal(trimLabel("  hello  "), "hello");
});
